head.b:skin:
/*
 * Blogger Template Style
 *
 * Sand Dollar
 * by Jason Sutter
 * Updated by Blogger Team
 */

/* Variable definitions
   ====================
   <Variable name="textcolor" description="Text Color"
             type="color" default="#000" value="#000000">

   <Variable name="bgcolor" description="Page Background Color"
             type="color" default="#f6f6f6" value="#f6f6f6">

   <Variable name="pagetitlecolor" description="Blog Title Color"
             type="color" default="#F5DEB3" value="#ffffff">

   <Variable name="pagetitlebgcolor" description="Blog Title Background Color"
             type="color" default="#DE7008" value="#f6f6f6">

  <Variable name="descriptionColor" description="Blog Description Color"
            type="color" default="#9E5205"  value="#04519e"/>

   <Variable name="descbgcolor" description="Description Background Color"
             type="color" default="#F5E39e" value="#f6f6f6">

   <Variable name="titlecolor" description="Post Title Color"
             type="color" default="#9E5205" value="#444444">

   <Variable name="datecolor" description="Date Header Color"
             type="color" default="#777777" value="#777777">

   <Variable name="footercolor" description="Post Footer Color"
             type="color" default="#444444" value="#444444">

   <Variable name="linkcolor" description="Link Color"
             type="color" default="#DE7008" value="#777777">

   <Variable name="footerlinkcolor" description="Post Footer Link Color"
             type="color" default="#968a0a" value="#29024f">

   <Variable name="visitedlinkcolor" description="Visited Link Color"
             type="color" default="#DE7008" value="#000000">

   <Variable name="sidebarcolor" description="Sidebar Title Color"
             type="color" default="#B8A80D" value="#777777">

   <Variable name="sidebarlinkcolor" description="Sidebar Link Color"
             type="color" default="#999999" value="#999999">

   <Variable name="bordercolor" description="Border Color"
             type="color" default="#e0ad12" value="#283b4f">

   <Variable name="bodyfont" description="Text Font"
             type="font"
             default="normal normal 100% 'Trebuchet MS',Trebuchet,Verdana,Sans-Serif" value="normal normal 126% 微軟正黑體,Verdana, sans-serif">

   <Variable name="headerfont" description="Sidebar Title Font"
             type="font"
             default="normal bold 150% 微軟正黑體,Verdana,Sans-serif" value="normal bold 110% Verdana,Sans-serif">

   <Variable name="dateHeaderFont" description="Date Header Font"
             type="font"
             default="normal bold 105% 'Trebuchet MS',Trebuchet,Verdana,Sans-serif" value="normal bold 105% &#39;Trebuchet MS&#39;,Trebuchet,Verdana,Sans-serif">

   <Variable name="pagetitlefont" description="Blog Title Font"
             type="font" default="normal bold 300% 微軟正黑體,Verdana,Sans-Serif" value="italic bold 262% Georgia, Utopia, &#39;Palatino Linotype&#39;, Palatino, serif;">

   <Variable name="titlefont" description="Post Title Font"
             type="font" default="normal bold 160% 微軟正黑體,Verdana,Sans-Serif" value="normal bold 160% 微軟正黑體, Verdana,Sans-Serif">
   <Variable name="startSide" description="Start side in blog language"
             type="automatic" default="left">
   <Variable name="endSide" description="End side in blog language"
             type="automatic" default="right">
*/

body {
  margin:0px;
  padding:0px;
  background:$bgcolor;
  color:$textcolor;
  font-size: small;
}

#outer-wrapper {
  font:$bodyfont;
}

a {
 color:$linkcolor;
} 

a:hover {
 color:$titlecolor;
} 

a img { 
  border-width: 0;
}

.shadow {
float: left;
width: auto;
background: url(http://sites.google.com/site/blogtools2ch/img/fuzzy_shadow.png) no-repeat bottom right;
}
.shadow div {
background: url(http://sites.google.com/site/blogtools2ch/img/fuzzy_shadow1.png) no-repeat right top;
}
.shadow div a {
background: url(http://sites.google.com/site/blogtools2ch/img/fuzzy_shadow2.png) no-repeat left bottom;
padding: 0 6px 6px 0;
display: block;
}
.shadow img {
background-color: #fff;
color: #000;
border: 1px solid #999;
padding: 4px;
vertical-align: bottom;
}


/* ---- 隱藏導覽列1/2 navBar ---- */
.navbar {
    position: fixed; /* 黏在上方 */
    width: 100%;
    height: 28px;
    left: 0px; 
    z-index: 99; /* 圖層順序設成 99 避免被其他物件蓋住 */
}
.navbar div {
    display: none;
}

#content-wrapper {
  padding-top: 0;
  padding-$endSide: 1em;
  padding-bottom: 0;
  padding-$startSide: 1em;
}

@media all  {
  div#main {
    float:$endSide;
    width:80%;
    padding-top:30px;
    padding-$endSide:0;
    padding-bottom:10px;
    padding-$startSide:1em;
    border-$startSide:dotted 1px $bordercolor;
    word-wrap: break-word; /* fix for long text breaking sidebar float in IE */
    overflow: hidden;     /* fix for long non-text content breaking IE sidebar float */
  } 			  
  div#sidebar {
    margin-top:20px;
    margin-$endSide:0px;
    margin-bottom:0px;
    margin-$startSide:0;
    padding:0px;
    text-align:$startSide; 
    float: $startSide;
    width: 18%;
    word-wrap: break-word; /* fix for long text breaking sidebar float in IE */
    overflow: hidden;     /* fix for long non-text content breaking IE sidebar float */
  } 
} 

@media handheld  {
  div#main {
   float:none;
   width:90%; 
 } 

  div#sidebar {
    padding-top:30px;
    padding-$endSide:7%;
    padding-bottom:10px;
    padding-$startSide:3%;
  }                          
}

#header { 
  padding-top:0px;
  padding-$endSide:0px;
  padding-bottom:0px;
  padding-$startSide:0px;
  margin-top:0px;
  margin-$endSide:0px;
  margin-bottom:0px;
  margin-$startSide:0px;
  border-bottom:dotted 1px $bordercolor;
  background:$descbgcolor;
}

h1 a:link  {
 text-decoration:none;
 color:$pagetitlecolor
} 

h1 a:visited  {
  text-decoration:none;
  color:$pagetitlecolor
} 

h1,h2,h3 {
  margin: 0;
}

h1 { 
  padding-top:25px;
  padding-$endSide:0px;
  padding-bottom:10px;
  padding-$startSide:5%;
  color:$pagetitlecolor;
  background:$pagetitlebgcolor;
  font:$pagetitlefont;
  letter-spacing:-2px; 
} 

h3.post-title { 
  color:$titlecolor;
  font:$titlefont;
  letter-spacing:-1px;
}

h3.post-title a,
h3.post-title a:visited { 
  color: $titlecolor;
}

h2.date-header  {
  margin-top:10px;
  margin-$endSide:0px;
  margin-bottom:0px;
  margin-$startSide:0px;
  color:$datecolor;
  font: $dateHeaderFont;
}

h4 {
 color:#aa0033; 
} 

#sidebar h2 { 
  color:$sidebarcolor;
  margin:0px; 
  padding:0px;
  font:$headerfont;
}

#sidebar .widget {
  margin-top:0px;
  margin-$endSide:0px;
  margin-bottom:33px;
  margin-$startSide:0px;
  padding-top:0px;
  padding-$endSide:0px;
  padding-bottom:0px;
  padding-$startSide:0px;
  font-size:90%; 
} 

#sidebar ul {
  list-style-type:none;
  padding-$startSide: 0;
  margin-top: 0;
}

#sidebar li {
  margin-top:0px;
  margin-$endSide:0px;
  margin-bottom:0px;
  margin-$startSide:0px;
  padding-top:0px;
  padding-$endSide:0px;
  padding-bottom:0px;
  padding-$startSide:0px;
  list-style-type:none;
  font-size:95%; 
} 

.description {
  padding:0px;
  margin-top:7px;
  margin-$endSide:12%;
  margin-bottom:7px;
  margin-$startSide:5%;
  color:$descriptionColor;
  background:transparent;
  font:bold 100% Verdana,Sans-Serif;
}

 .post {
  margin-top:0px;
  margin-$endSide:0px;
  margin-bottom:30px;
  margin-$startSide:0px;
} 

.post strong {
  color:$textcolor;
  font-weight:bold; 
} 

pre,code {
 color:$sidebarlinkcolor;
} 

strike {
 color:$sidebarlinkcolor;
} 

.post-footer  {
  padding:0px;
  margin:0px;
  color:$footercolor;
  font-size:80%; 
} 
.post-footer a {
  border:none;
  color:$footerlinkcolor;
  text-decoration:none; 
} 

.post-footer a:hover {
  text-decoration:underline; 
} 

#comments {
  padding:0px;
  font-size:110%;
  font-weight:bold;
}

.comment-author { 
  margin-top: 10px;
 }

.comment-body {
  font-size:100%;
  font-weight:normal;
  color:black; 
} 

.comment-footer {
  padding-bottom:20px;
  color:$footercolor;
  font-size:80%;
  font-weight:normal;
  display:inline;
  margin-$endSide:10px 
} 

.deleted-comment  {
  font-style:italic;
  color:gray; 
} 

.comment-link  {
  margin-$startSide:.6em;
} 

.profile-textblock { 
  clear: both;
  margin-$startSide: 0;
}

.profile-img { 
  float: $startSide;
  margin-top: 0;
  margin-$endSide: 5px;
  margin-bottom: 5px;
  margin-$startSide: 0;
  border: 2px solid $pagetitlebgcolor;
}

#sidebar a:link  {
  color:$sidebarlinkcolor;
  text-decoration:none; 
}    

#sidebar a:active  {
  color:#ff0000;
  text-decoration:none; 
}     

#sidebar a:visited  {
  color:sidebarlinkcolor;
  text-decoration:none; 
} 

#sidebar a:hover {
  color:$sidebarcolor;
  text-decoration:none; 
} 

.feed-links {
  clear: both;
  line-height: 2.5em;
}

#blog-pager-newer-link {
  float: $startSide;
 }

#blog-pager-older-link {
  float: $endSide;
}

#blog-pager {   
  text-align: center; 
}

.clear { 
  clear: both;
}

.widget-content { 
  margin-top: 0.5em;
}

/** Tweaks for layout editor preview */

body#layout #outer-wrapper { 
  margin-top: 0;
}

body#layout #main,
body#layout #sidebar { 
  margin-top: 10px;
  padding-top: 0;
}

b:if.script:
google.load("annotations", "1", {"locale": ""});
function initialize() {
  google.annotations.setApplicationId();
  google.annotations.createAll();
  google.annotations.fetch();
}
google.setOnLoadCallback(initialize);

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//
